/**
 * Die Ausleger auf Deutsch, aus dem Englischen in `fathersBio.en.ts`
 * übertragen. Schweizer Schreibweise (kein Eszett), Absätze durch Leerzeilen.
 */
import type { BioSections } from './fathersBio';

export const BIO_DE: Record<string, BioSections> = {
	augustine: {
		dates: '354–430 · Tagaste, Mailand, Hippo',
		life: `Am 13. November 354 in Tagaste in Numidien als Sohn eines heidnischen Vaters und der Christin Monika geboren, lehrte Augustinus Rhetorik in Karthago, Rom und Mailand, war neun Jahre Hörer bei den Manichäern und hatte mit einer Konkubine, die er nie nennt, einen Sohn, Adeodatus. In Mailand lösten die Predigt des Ambrosius und die Bücher der Platoniker seine Einwände; in einem Garten las er im August 386 auf den Kinderruf «tolle, lege» hin Röm 13,13 und gab die Welt auf. Ambrosius taufte ihn an Ostern 387; Monika starb auf der Heimreise in Ostia.

In Afrika wollte er als Mönch leben. Das Volk von Hippo zwang ihn 391 zum Priester, 395 wurde er Bischof und blieb es fünfunddreissig Jahre: predigend, richtend, Briefe und rund hundert Bücher schreibend. Er starb am 28. August 430, während die Vandalen die Stadt belagerten, die Busspsalmen an die Wand seines Zimmers geheftet.`,
		teaching: `Die Bekenntnisse machten sein eigenes Leben zum Gebet und das unruhige Herz zum Bild jeder Seele: «Du hast uns auf dich hin geschaffen, und unruhig ist unser Herz, bis es ruht in dir.» Der Gottesstaat las die Plünderung Roms als den Gang zweier Städte, auf zwei Lieben gebaut, durch eine Geschichte. De Trinitate suchte die Dreifaltigkeit in Gedächtnis, Einsicht und Willen des Geistes.

Gegen die Manichäer lehrte er, das Böse sei keine Substanz, sondern Mangel an Gutem; gegen die Donatisten, ein Sakrament sei Christi Werk und hänge nicht von der Heiligkeit des Spenders ab; gegen Pelagius, die Gnade gehe jedem guten Werk voraus und niemand könne sich selbst retten. «Glaube, damit du verstehst; verstehe, damit du glaubst» ist seine Regel für Glaube und Vernunft.`,
		church: `Benedikt XVI. nannte ihn «den grössten Vater der lateinischen Kirche» und widmete ihm fünf Katechesen (2008). Er ist einer der vier ursprünglichen lateinischen Kirchenlehrer (1298); seine Lehre von Gnade, Sakramenten und Kirche durchzieht das Konzil von Trient und den Katechismus. Wo der Jansenismus seine späten Schriften zur Prädestination verhärtete, las die Kirche ihn mit dem Konzil von Orange (529): Die Gnade ist allen angeboten, die Freiheit ist wirklich. Seine Regel befolgen bis heute viele Orden.`,
		particular: `In De Trinitate II–IV hält Augustinus die Gotteserscheinungen des Alten Testaments, den brennenden Dornbusch, die Besucher bei Mamre, das Feuer am Sinai, für geschaffene Zeichen, durch Engel gewirkt, in denen jede Person oder die ganze Dreifaltigkeit sprechen konnte. Alle früheren Väter, Justin, Irenäus, Tertullian, Hilarius und Ambrosius, hatten darin den Sohn vor seiner Menschwerdung gesehen. Augustins Lesart wurde im Westen zur Norm. Er wandte sich auch gegen die Todesstrafe für Häretiker und ging am Ende seines Lebens in den Retractationes alle seine Bücher durch, um sich selbst zu korrigieren.`,
		feast: '28. August',
		titles: 'Kirchenlehrer · Lehrer der Gnade'
	},
	chrysostom: {
		dates: 'um 349–407 · Antiochia, Konstantinopel, Komana',
		life: `In Antiochia geboren und von seiner verwitweten Mutter Anthusa erzogen, studierte Johannes Rhetorik beim Heiden Libanios und die Schrift bei Diodor von Tarsus. Sechs Jahre lebte er als Mönch und Einsiedler in den Bergen, ruinierte seine Gesundheit mit Nachtwachen und kehrte zurück, um Diakon (381) und Priester (386) zu werden. Zwölf Jahre predigte er in Antiochia fast täglich; die Säulenhomilien, gehalten, während die Stadt nach einem Aufruhr die Rache des Kaisers erwartete, machten ihn berühmt.

398 wurde er heimlich nach Konstantinopel geholt und zum Bischof gemacht. Er kürzte den Haushalt, speiste die Armen, disziplinierte den Klerus und predigte gegen den Luxus des Hofes. Die Kaiserin Eudoxia und Theophilus von Alexandrien liessen ihn auf der Eichensynode (403) absetzen; vom erschrockenen Volk zurückgerufen, wurde er 404 erneut verbannt, nach Kukusos in Armenien. In der Sommerhitze weitergetrieben, starb er am 14. September 407 in Komana mit den Worten «Ehre sei Gott für alles».`,
		teaching: `Johannes war der Meister der antiochenischen Schule: Er erklärte den Text Vers für Vers in seinem einfachen Sinn und zog daraus die Lehre für die Gemeinde vor ihm. Über siebenhundert seiner Homilien sind erhalten, zu Genesis, Psalmen, Matthäus, Johannes, Apostelgeschichte, Römer, Korinther, Hebräer, das grösste Auslegungswerk eines griechischen Vaters.

Seine Predigt kehrte immer wieder zu den Armen als dem Sakrament Christi zurück, zum Almosen, zur Eucharistie mit brennendem Herzen, zur Familie als «kleiner Kirche», in der die Schrift zu Hause gelesen wird.`,
		church: `1568 zum Kirchenlehrer erklärt, einer der drei Heiligen Hierarchen des byzantinischen Kalenders, 1908 von Pius X. zum Patron der Prediger ernannt. Die Göttliche Liturgie des byzantinischen Ritus trägt seinen Namen. Benedikt XVI. widmete ihm zwei Katechesen (2007), zu seiner Soziallehre und zur Kirche als Leib Christi; 2004 gab Rom seine Reliquien an Konstantinopel zurück.`,
		particular: `Bei «Du bist Petrus» versteht er den Felsen als das Glaubensbekenntnis des Petrus, eine Lesart, die die katholische Auslegung mit der Person des Petrus zusammenhält. Acht Predigten von 386–387 gegen die judaisierenden Christen Antiochias gebrauchen die gewaltsame Rhetorik der Zeit gegen die Juden; die Kirche liest sie als Produkt ihrer Epoche, nicht als Lehre.`,
		feast: '13. September',
		titles: 'Kirchenlehrer · «Goldmund»'
	},
	jerome: {
		dates: 'um 347–420 · Stridon, Rom, Bethlehem',
		life: `Hieronymus wurde in Stridon an der Grenze Dalmatiens geboren und studierte in Rom Grammatik und Rhetorik bei Donatus; dort wurde er getauft. Nach Jahren in Trier und Aquileia ging er in den Osten und lebte als Einsiedler in der Wüste von Chalkis (374–379), wo er bei einem getauften Juden Hebräisch lernte, um seiner Versuchungen Herr zu werden. In Antiochia geweiht, hörte er Gregor von Nazianz in Konstantinopel und diente Papst Damasus in Rom als Sekretär (382–385); der Papst bat ihn, die lateinischen Evangelien zu überarbeiten.

Nach dem Tod des Damasus von den Feinden, die seine Zunge ihm gemacht hatte, aus Rom vertrieben, liess er sich 386 mit Paula und deren Tochter Eustochium in Bethlehem nieder, gründete ein Männer- und ein Frauenkloster und arbeitete dort bis zu seinem Tod am 30. September 420.`,
		teaching: `Sein Lebenswerk ist die Vulgata: die Evangelien nach dem Griechischen verbessert, das Alte Testament neu aus dem Hebräischen übersetzt (die «hebräische Wahrheit»), gegen den Wunsch Augustins, bei der Septuaginta zu bleiben. Sie wurde für über tausend Jahre die Bibel der lateinischen Kirche. Er schrieb Kommentare zu den Propheten, Matthäus und Galater, den Katalog De viris illustribus und Briefe über das asketische Leben, die wie Traktate gelesen wurden.

«Die Schrift nicht kennen heisst Christus nicht kennen», aus seinem Vorwort zu Jesaja, zitiert das Zweite Vatikanum als Grund, warum jeder Christ die Bibel lesen soll.`,
		church: `Einer der vier ursprünglichen lateinischen Kirchenlehrer. Das Konzil von Trient erklärte seine Vulgata zur authentischen lateinischen Bibel (1546). Benedikt XVI. stellte ihn (2007) als Vorbild einer Schriftliebe vor, die zur Christusliebe wird, und Franziskus beging den 1600. Todestag mit dem Schreiben Scripturae Sacrae affectus (2020).`,
		particular: `Hieronymus zweifelte an den deuterokanonischen Büchern: Seine Vorreden nennen sie erbauliche Lektüre, nicht Glaubensregel, obwohl er Tobit und Judit für den Papst übersetzte. Die Kirche behielt die Bücher und nannte sie in Trient kanonisch. Seine Streitigkeiten mit Rufinus über Origenes, mit Jovinian und Helvidius über die Jungfräulichkeit Marias, mit Vigilantius über die Reliquien zeigen ein Temperament, das seine Freunde fürchteten. Der Löwe zu seinen Füssen auf den Bildern ist eine von einem anderen Heiligen entlehnte Legende.`,
		feast: '30. September',
		titles: 'Kirchenlehrer'
	},
	ambrose: {
		dates: 'um 340–397 · Trier, Mailand',
		life: `In Trier als Sohn eines Prätorianerpräfekten Galliens geboren, wurde Ambrosius Jurist und Statthalter von Aemilia-Ligurien in Mailand. Als 374 der arianische Bischof starb und die Parteien um den Nachfolger stritten, rief eine Stimme aus der Menge, ein Kind, hiess es, «Ambrosius Bischof». Er war noch Katechumene. Binnen einer Woche wurde er getauft und geweiht, am 7. Dezember.

Er gab sein Vermögen der Kirche, lernte Griechisch, um Philon, Origenes und Basilius zu lesen, und predigte so gut, dass der junge Augustinus kam, um den Stil zu hören, und der Sache wegen blieb. Die Basiliken Mailands hielt er 385–386 gegen den arianischen Hof, indem er sie mit dem Volk und seinen Hymnen füllte, und 390 liess er den Kaiser Theodosius für das Blutbad von Thessalonich öffentlich Busse tun. Er starb am Karsamstag 397.`,
		teaching: `Ambrosius brachte die allegorische Schriftlesung der Griechen in den Westen und unterwies die Neugetauften aus den Sakramenten selbst (De mysteriis, De sacramentis). Seine Hymnen, darunter «Aeterne rerum conditor», begründeten die lateinische Hymnendichtung. De officiis ministrorum gab dem Klerus eine Ethik nach Ciceros Plan; seine Schriften über die Jungfräulichkeit machten Maria zum Urbild der Kirche.

Sein Wort an Theodosius, «der Kaiser ist in der Kirche, nicht über ihr», bestimmte das Verhältnis von Kirche und Staat für das Mittelalter.`,
		church: `Einer der vier ursprünglichen lateinischen Kirchenlehrer. Der Mailänder Ritus trägt bis heute seinen Namen. Benedikt XVI. stellte ihn (2007) als Meister der «lectio divina» und einer Katechese aus den Mysterien vor, als den Bischof, der Augustinus ebenso durch sein Leben wie durch seine Worte bekehrte.`,
		particular: `Augustinus sah ihn lesen, ohne die Lippen zu bewegen, und hielt es in den Bekenntnissen als etwas Seltsames fest. Ambrosius hielt den Engel des Herrn, der im Alten Testament erscheint, für Christus, die Lesart aller Väter, bevor Augustinus sie änderte.`,
		feast: '7. Dezember',
		titles: 'Kirchenlehrer'
	},
	'gregory-great': {
		dates: 'um 540–604 · Rom, Konstantinopel',
		life: `Aus einer römischen Senatorenfamilie stammend, war Gregor mit etwa dreissig Stadtpräfekt. 574 machte er sein Haus auf dem Caelius zum Andreaskloster und wurde Mönch. Papst Pelagius II. weihte ihn zum Diakon und sandte ihn als Gesandten nach Konstantinopel (579–586). Als der Papst 590 an der Pest starb, wählten ihn Klerus und Volk; er versuchte zu fliehen und war vom 3. September 590 bis zum 12. März 604 Papst, der erste Mönch auf dem Stuhl Petri.

Er ernährte Rom aus den päpstlichen Gütern, während die Langobarden es belagerten, und schloss selbst Frieden mit ihnen, als der Exarch des Kaisers es nicht tat. 596 sandte er Augustinus mit vierzig Mönchen zur Bekehrung der Angelsachsen. Er nannte sich «Knecht der Knechte Gottes», ein Titel, den die Päpste noch führen.`,
		teaching: `Die Moralia zu Ijob, fünfunddreissig Bücher, seinen Mönchen gepredigt, lasen das ganze christliche Leben aus einem Buch der Schrift. Die Regula pastoralis wurde das Handbuch jedes Bischofs im Mittelalter; Alfred der Grosse übersetzte sie ins Englische. Die Dialoge erzählten die Wunder der italienischen Heiligen und gaben dem Westen das Leben Benedikts; seine vierzig Evangelienhomilien wurden tausend Jahre an Sonntagen gelesen.

Er lehrte, «die Schrift wächst mit dem, der sie liest»: Der moralische Sinn, die Lesung, die ein Leben verändert, war ihm das Wichtigste.`,
		church: `Einer der vier ursprünglichen lateinischen Kirchenlehrer. Benedikt XVI. widmete ihm zwei Katechesen (2008), zu seiner Regierung Roms und zu seiner Lehre. Das gregorianische Sakramentar und der «gregorianische» Choral tragen seinen Namen nach einer Überlieferung des neunten Jahrhunderts; der Choral stammt nicht von ihm, und die liturgischen Bücher unter seinem Namen wurden nach ihm aufgebaut.`,
		particular: `Er konnte kein Griechisch, misstraute der Philosophie und erwartete das nahe Ende der Welt; seine Dialoge berichten Visionen des Fegefeuers, die die westliche Vorstellung des Jenseits prägten. Die Mission zu den Angelsachsen entstand nach Bedas Erzählung aus einem Blick auf blonde Sklavenknaben auf dem römischen Markt: «nicht Angeln, sondern Engel».`,
		feast: '3. September',
		titles: 'Kirchenlehrer'
	},
	bede: {
		dates: '672/3–735 · Wearmouth, Jarrow',
		life: `Beda wurde mit sieben Jahren dem Kloster Wearmouth in Northumbrien übergeben und zog in dessen Tochterhaus Jarrow, wo er sein ganzes Leben verbrachte. Mit neunzehn wurde er Diakon, mit dreissig Priester, und «unter der Beobachtung der Regel und der täglichen Pflicht des Gesangs in der Kirche», wie er sagt, war es seine Freude, zu lernen, zu lehren und zu schreiben. Er starb am 26. Mai 735, nachdem er gerade eine englische Übersetzung des Johannesevangeliums zu Ende diktiert hatte.`,
		teaching: `Er schrieb Kommentare zu einem grossen Teil der Bibel, zu Genesis, Samuel, Esra, Tobit, Markus, Lukas, Apostelgeschichte, den katholischen Briefen und der Offenbarung, indem er die Väter in eine Form brachte, die ein Mönch seiner Zeit gebrauchen konnte, und seine Entlehnungen am Rand kennzeichnete, damit niemand Augustins Worte für seine eigenen hielte. Die Kirchengeschichte des englischen Volkes (731) ist die Quelle fast alles dessen, was man vom frühen England weiss. Sein De temporum ratione machte die Jahreszählung ab Christi Geburt, «anno Domini», zur Norm des Westens.`,
		church: `Leo XIII. erklärte ihn 1899 zum Kirchenlehrer, dem einzigen Engländer unter ihnen. Der Titel «der Ehrwürdige» ist seit dem Jahrhundert nach seinem Tod der seine, bestätigt vom Konzil von Aachen 836. Benedikt XVI. stellte ihn (2009) als den Lehrer vor, der Gelehrsamkeit und Liturgie verband und die Geschichte zur Schule des Glaubens machte.`,
		particular: `Beda verliess seinen Winkel Northumbriens nie und hatte nie ein höheres Amt als das Priestertum, doch seine Kommentare wurden binnen einer Generation in ganz Europa abgeschrieben und speisten die Glossa Ordinaria und die Catena Aurea. Seine Lesart ist fast ganz allegorisch: Tempel, Zelt und Bundeslade werden zur Kirche.`,
		feast: '25. Mai',
		titles: 'Kirchenlehrer · der Ehrwürdige'
	},
	origen: {
		dates: 'um 185–253/4 · Alexandrien, Caesarea',
		life: `Sohn des Leonides, der 202 in Alexandrien den Märtyrertod starb, während der Knabe ihm Briefe zur Ermutigung schrieb, wurde Origenes mit achtzehn Leiter der Katechetenschule. Er lebte in äusserster Strenge, und Eusebius berichtet, er habe Mt 19,12 wörtlich genommen und sich selbst entmannt. 230 in Caesarea ohne Erlaubnis seines Bischofs zum Priester geweiht, wurde er aus Alexandrien ausgeschlossen und zog 231 nach Caesarea in Palästina, wo ein Gönner sieben Stenographen bezahlte, die seine Vorlesungen aufnahmen.

In der Verfolgung des Decius (250) wurde er eingekerkert und gefoltert und starb wenige Jahre später in Tyrus an den Folgen, ein Bekenner, wenn nicht ein Märtyrer.`,
		teaching: `Origenes war der erste Christ, der die ganze Schrift kommentierte, in Kommentaren, Homilien und Scholien, und der erste, der eine systematische Theologie entwarf (De principiis). Die Hexapla stellte den hebräischen Text und vier griechische Versionen in sechs Spalten nebeneinander. Gegen Celsus schrieb er die gelehrteste Verteidigung des Christentums der alten Kirche.

Er las die Schrift nach 1 Thess 5,23 auf drei Ebenen: dem Leib des Buchstabens, der Seele des moralischen Sinns und dem Geist des Mysteriums, wobei die dritte das Ziel ist. Die Lehre des Katechismus von den Schriftsinnen stammt von ihm ab.`,
		church: `Origenes wurde nie heiliggesprochen. Gewisse seiner Spekulationen, die Präexistenz der Seelen, die Wiederherstellung aller Dinge einschliesslich des Teufels, eine Unterordnung des Sohnes, wurden als «Origenismus» in den Streitigkeiten um 400, im Edikt Justinians 543 und auf dem Zweiten Konzil von Konstantinopel (553) verurteilt, wobei die Forschung bezweifelt, dass die Anathemata beschreiben, was er selbst lehrte. Die Catholic Encyclopedia nennt ihn keinen Förderer der Häresie; Benedikt XVI. nannte ihn (2007) «eine der bemerkenswertesten Gestalten der Geschichte des christlichen Denkens» und lobte seinen «Primat der Schrift».`,
		particular: `Seine Allegorie konnte die Widersprüche der Evangelien als vom Geist gewollt behandeln, um den Leser über den Buchstaben hinauszuzwingen. Der Universalismus, der ihn vom Kalender fernhielt, die Hoffnung, am Ende würden alle gerettet, kehrte bei Gregor von Nyssa und in der modernen Theologie wieder als Frage, die die Kirche für den Einzelnen offen und als Lehre geschlossen hat.`
	},
	'cyril-alexandria': {
		dates: 'um 376–444 · Alexandrien',
		life: `Neffe des Patriarchen Theophilus, den er zur Eichensynode begleitete, die Chrysostomus absetzte, wurde Kyrill 412 Patriarch von Alexandrien. Seine ersten Jahre waren gewaltsam: Er schloss die Kirchen der Novatianer, vertrieb nach Unruhen Juden aus der Stadt und bekämpfte den Präfekten Orestes; die Ermordung der Philosophin Hypatia durch einen christlichen Mob 415 legen ihm Kritiker zur Last, doch keine Quelle macht ihn zum Anstifter.

Ab 428 trat er gegen Nestorius von Konstantinopel auf, der Maria nicht Gottesgebärerin nennen wollte. Er führte den Vorsitz auf dem Konzil von Ephesus (431), das er eröffnete, bevor die antiochenischen Bischöfe eintrafen, und versöhnte sich mit ihnen in der Unionsformel von 433. Er starb am 27. Juni 444.`,
		teaching: `Kyrill lehrte, dass die eine Person des Wortes das einzige Subjekt des Göttlichen und des Menschlichen in Christus ist, so dass, was der Mensch Jesus tat und litt, Gott das Wort im Fleisch tat und litt. Maria ist darum Theotokos, Gottesgebärerin, und die Eucharistie lebenspendend, weil sie das Fleisch des Wortes ist. Seine Kommentare zu Johannes, Lukas, dem Pentateuch und den Propheten lesen das Alte Testament als Weissagung Christi.`,
		church: `Leo XIII. erklärte ihn 1882 zum Kirchenlehrer. Das Dogma von Ephesus ist das seine; das Konzil von Chalkedon (451) las seine Briefe neben dem Tomus Leos. Benedikt XVI. nannte ihn (2007) «den Wächter der Genauigkeit» im Glauben. Die Formel «eine fleischgewordene Natur des Gottes Wortes», die er einer Fälschung des Apollinaris unter dem Namen des Athanasius entnahm, diente später den Monophysiten, die Chalkedon ablehnten.`,
		particular: `Kyrill ist der Vater, dessen Lehre die Kirche festhält und dessen Methoden sie nicht verteidigt. Der Historiker Sokrates, kein Freund, und die Catholic Encyclopedia unterscheiden gleichermassen den rücksichtslosen Politiker vom Theologen der Menschwerdung. Er ist der Lehrer des Marientitels.`,
		feast: '27. Juni',
		titles: 'Kirchenlehrer · Lehrer der Menschwerdung'
	},
	basil: {
		dates: 'um 330–379 · Caesarea in Kappadokien',
		life: `Basilius wurde in eine Familie von Heiligen geboren: Seine Grossmutter Makrina, seine Eltern, seine Schwester Makrina und seine Brüder Gregor von Nyssa und Petrus von Sebaste werden alle verehrt. Er studierte in Konstantinopel und Athen mit Gregor von Nazianz, kehrte als gefeierter Rhetor zurück und wurde von seiner Schwester zum asketischen Leben bekehrt. Nach einer Reise zu den Mönchen Ägyptens und Syriens gründete er eine Gemeinschaft am Fluss Iris, wo Gregor zu ihm stiess.

362 Priester, 370 Bischof von Caesarea, trat er dem arianischen Kaiser Valens persönlich entgegen: «Vielleicht seid Ihr noch nie einem Bischof begegnet.» Vor Caesarea baute er eine ganze Stadt aus Spitälern, Hospizen und Werkstätten, die Basileias, und starb erschöpft am 1. Januar 379, vor dem Konzil, das seinen Glauben bestätigte.`,
		teaching: `Seine zwei Mönchsregeln in Fragen und Antworten machten das gemeinsame Leben zur Norm des östlichen Mönchtums und prägten Benedikts Regel im Westen. Über den Heiligen Geist verteidigte die Gottheit und gleiche Ehre des Geistes, ohne das Wort «Gott» von ihm auszusprechen, eine Zurückhaltung, die er für seelsorglich hielt und Gregor von Nazianz für zu vorsichtig. Die Homilien zum Sechstagewerk lehrten ein christliches Publikum die Schönheit der Welt. Die Basiliusliturgie wird im byzantinischen Ritus noch in der Fastenzeit gefeiert.`,
		church: `Kirchenlehrer, einer der drei Heiligen Hierarchen des Ostens. Benedikt XVI. widmete ihm zwei Katechesen (2007), zu seinen Predigten über Reichtum und Hunger: «Das Brot, das du zurückhältst, gehört dem Hungrigen, der Mantel in deinem Schrank dem Nackten.»`,
		particular: `Er legte das Vokabular der Dreifaltigkeit fest, ein Wesen in drei Hypostasen, das das Konzil von 381 übernahm. Die Spannung zwischen ihm und Gregor von Nazianz, den er zum Bischof eines ungewollten Dorfes machte, um eine Stimme zu gewinnen, steht in Gregors Gedichten.`,
		feast: '2. Januar',
		titles: 'Kirchenlehrer · der Grosse'
	},
	'gregory-nazianzen': {
		dates: 'um 330–390 · Nazianz, Konstantinopel',
		life: `Sohn des Bischofs von Nazianz, studierte Gregor in Athen mit Basilius und hätte sein Leben gern mit Büchern und Gebet verbracht. Sein Vater weihte ihn 361 gegen seinen Willen zum Priester; Basilius machte ihn 372 zum Bischof von Sasima, ein Amt, das er nie antrat. 379 rief ihn die kleine nizänische Gemeinde Konstantinopels in die Hauptstadt, wo er in einer Hauskapelle die Fünf Theologischen Reden hielt, die ihm seinen Titel gaben.

Eine Zeitlang führte er den Vorsitz auf dem Konzil von 381, wurde als Bischof angefochten und trat mitten darin mit einer Abschiedsrede zurück. Er zog sich nach Arianz zurück, um Gedichte zu schreiben, und starb dort 390.`,
		teaching: `Die Theologischen Reden setzten die Begriffe der Trinitätslehre: eine Natur, drei Personen, der Sohn gezeugt, der Geist hervorgehend, und der Geist ganz Gott, was Basilius nicht laut gesagt hatte. Gegen Apollinaris prägte er die Regel der Menschwerdung: «Was nicht angenommen wurde, ist nicht geheilt», Christus hat also einen menschlichen Geist. Seine Reden zu Ostern, Epiphanie und Pfingsten werden in der byzantinischen Liturgie gelesen; seine Gedichte, dreissigtausend Verse, enthalten die erste christliche Autobiographie in Versen.`,
		church: `Kirchenlehrer und einer der drei Heiligen Hierarchen. Der Osten nennt ihn «den Theologen», ein Titel, den er nur ihm, dem Evangelisten Johannes und Symeon gibt. Benedikt XVI. widmete ihm zwei Katechesen (2007), zu seiner Freundschaft mit Basilius und zu seiner Theologie als Lobpreis.`,
		particular: `Der empfindsamste der Väter: Er floh jedes Amt, das man ihm gab, trauerte um die Freundschaft, die Basilius belastet hatte, und verliess das Konzil von 381 mit den Worten «lasst mich ruhen von meinen Mühen». Er ist der Dichter unter den Lehrern.`,
		feast: '2. Januar',
		titles: 'Kirchenlehrer · der Theologe'
	},
	'gregory-nyssa': {
		dates: 'um 335–nach 394 · Nyssa',
		life: `Der jüngere Bruder des Basilius lehrte Rhetorik und war verheiratet, bevor sein Bruder ihn 372 zum Bischof der kleinen Stadt Nyssa machte. Arianische Intrigen liessen ihn 376 wegen Misswirtschaft absetzen; 378 wurde er wieder eingesetzt, spielte auf dem Konzil von 381 eine führende Rolle und hielt die Grabreden auf die kaiserliche Familie. Er starb nach 394.`,
		teaching: `Gregor ist der spekulativste der Kappadokier. Das Leben des Mose liest den Aufstieg zum Sinai als endlosen Fortschritt der Seele in Gott hinein, «Epektasis», da das Unendliche nie ausgeschöpft werden kann. Über die Erschaffung des Menschen behandelt den Menschen als Bild Gottes; die Grosse Katechese ist eine Zusammenfassung des Glaubens für Lehrer. Seine Homilien zum Hohelied und zu den Seligpreisungen sind mystische Theologie; seine Predigten zum Kohelet waren die erste christliche Verurteilung der Sklaverei als solcher, weil sie gegen das Bild Gottes ist.`,
		church: `Ein Heiliger, aber kein Kirchenlehrer. Das Zweite Konzil von Konstantinopel (553) nannte ihn «Vater der Väter». Seine von Origenes ererbte Neigung zur Wiederherstellung aller Dinge wies die Kirche zurück, ohne ihn zu verurteilen; Photius und Germanus von Konstantinopel hielten die Stellen für interpoliert. Benedikt XVI. widmete ihm zwei Katechesen (2007).`,
		particular: `Seine Lehre von Gott als Dunkel, erkannt im Nichterkennen, nahmen Pseudo-Dionysius und die ganze mystische Tradition auf. Er hielt, dass Gottes Unendlichkeit bedeutet, dass das Verlangen der Seele nie endet, auch nicht im Himmel.`,
		feast: '10. Januar'
	},
	athanasius: {
		dates: 'um 300–373 · Alexandrien',
		life: `Athanasius nahm am Konzil von Nizäa (325) als Diakon und Sekretär des Bischofs Alexander teil und folgte ihm 328 nach. Fünfundvierzig Jahre war er der Verteidiger des Konzilsglaubens gegen die Arianer und die Kaiser, die sie begünstigten: fünfmal verbannt, siebzehn Jahre insgesamt, nach Trier, nach Rom, zu den Mönchen der Wüste, versteckt in seiner eigenen Stadt. «Athanasius gegen die Welt» wurde sprichwörtlich. Er starb in Frieden am 2. Mai 373.`,
		teaching: `Über die Menschwerdung argumentiert, das Wort sei Mensch geworden, «damit wir Gott würden»: Nur Gott kann retten, also muss der Retter Gott sein. Die Reden gegen die Arianer legen die ewige Zeugung des Sohnes und den Sinn von «wesensgleich» dar. Sein Leben des Antonius schuf die Mönchsbiographie und half, von Augustins Freunden gelesen, diesen zu bekehren. Sein Osterbrief von 367 ist die erste Liste genau der siebenundzwanzig Bücher des Neuen Testaments.`,
		church: `Kirchenlehrer und «Vater der Orthodoxie». Benedikt XVI. nannte ihn (2007) «den Unbeugsamen», der den Glauben von Nizäa rettete. Das sogenannte Athanasianische Glaubensbekenntnis, «Quicumque», ist ein lateinischer Text des fünften Jahrhunderts und nicht von ihm.`,
		particular: `Seine ganze Theologie ist die eine Frage, ob der Sohn geschaffen oder gezeugt ist; seine Feinde nannten ihn starrsinnig, seine Freunde die Säule der Kirche. Er gab die Mönche der Kirche und die Kirche den Mönchen.`,
		feast: '2. Mai',
		titles: 'Kirchenlehrer · Vater der Orthodoxie'
	},
	'cyril-jerusalem': {
		dates: 'um 315–386 · Jerusalem',
		life: `Von Bischof Maximus von Jerusalem zum Priester geweiht, wurde Kyrill um 350 Bischof und dreimal von den Arianern aus seinem Sitz vertrieben (357, 360, 367–378), über sechzehn Jahre im Exil. Zuerst gehörte er der Partei an, die dem Wort «wesensgleich» misstraute, und das Konzil von Konstantinopel (381), an dem er teilnahm, bestätigte seinen Glauben. Er starb am 18. März 386.`,
		teaching: `Seine vierundzwanzig Katechesen, mitgeschrieben, wie er sie in der Grabeskirche hielt, sind das vollständigste Bild davon, wie eine Kirche des vierten Jahrhunderts Christen machte: achtzehn Vorträge über das Glaubensbekenntnis für die Taufbewerber in der Fastenzeit, fünf «mystagogische» Vorträge in der Osterwoche über Taufe, Chrisam, Eucharistie und Liturgie. Von der Eucharistie sagt er, was Brot zu sein scheint, sei nicht Brot, sondern der Leib Christi.`,
		church: `Leo XIII. erklärte ihn 1883 zum Kirchenlehrer. Benedikt XVI. stellte (2007) seine Katechese als «ganzheitlich» vor, Leib, Seele und Geist durch Lehre, Sitten und Sakramente formend, und als Vorbild für die Katecheten von heute.`,
		particular: `Er vermied das nizänische Wort jahrzehntelang, während er seinen Sinn lehrte, ein Beispiel, das die Kirche für die Rechtgläubigkeit des Glaubens vor der Rechtgläubigkeit der Formel anführt. Sein Brief an Kaiser Constantius über ein Lichtkreuz, das 351 über Jerusalem gesehen wurde, ist der früheste solche Bericht.`,
		feast: '18. März',
		titles: 'Kirchenlehrer'
	},
	ephrem: {
		dates: 'um 306–373 · Nisibis, Edessa',
		life: `Ephräm diente den Bischöfen von Nisibis als Diakon und Katechet, und als die Stadt 363 an Persien abgetreten wurde, zog er mit den Christen nach Edessa. Er lehrte, schrieb und leitete Frauenchöre, die seine Hymnen sangen. Er starb am 9. Juni 373 an der Pest, während er die Kranken pflegte.`,
		teaching: `Seine Hymnen, die Madrasche, über den Glauben, das Paradies, die Geburt Christi, gegen die Häresien, sind Theologie in Bildern, nicht in Begriffen: Feuer und Geist im Brot, die Perle als Christus, Maria als zweite Eva und Mutter ohne Sünde. Seine Kommentare zur Genesis und zu Tatians Evangelienharmonie sind die früheste syrische Exegese. Man nennt ihn «die Harfe des Heiligen Geistes».`,
		church: `Benedikt XV. erklärte ihn 1920 zum Kirchenlehrer, dem einzigen syrischen. Benedikt XVI. stellte ihn (2007) als den Dichter vor, der zeigte, dass Theologie gesungen werden kann.`,
		particular: `Ephräm war nie Priester und weigerte sich stets, es zu werden; er ist der Diakon unter den Kirchenlehrern. Seine Hymnen wurden von Frauenchören gesungen, eine Rolle der Frauen in der Liturgie, die zu seiner Zeit ungewöhnlich war.`,
		feast: '9. Juni',
		titles: 'Kirchenlehrer · Harfe des Heiligen Geistes'
	},
	hilary: {
		dates: 'um 310–367 · Poitiers, Phrygien',
		life: `Ein Heide aus guter Familie, verheiratet und Vater einer Tochter, kam Hilarius durch das Lesen der Schrift zum Glauben und wurde um 350 zum Bischof von Poitiers gewählt. Als er sich weigerte, Athanasius zu verurteilen, verbannte ihn Kaiser Constantius nach Phrygien (356–360), wo er die griechische Theologie des Ostens kennenlernte und sein Hauptwerk schrieb. Er kehrte in ein Gallien zurück, das ihn willkommen hiess, und starb 367.`,
		teaching: `De Trinitate in zwölf Büchern ist die erste vollständige lateinische Darstellung der Lehre, geschrieben, um den Lateinern zu zeigen, dass der Glaube von Nizäa der der Schrift ist. In De synodis versuchte er, die «Homöusianer» des Ostens, die fürchteten, «wesensgleich» bedeute eine Person, mit den Nizänern zu versöhnen: eine Brücke, die dem Konzil von 381 half. Seine Kommentare zu Matthäus und den Psalmen sind die älteste vollständig erhaltene lateinische Exegese. Er schrieb auch die ersten lateinischen Hymnen.`,
		church: `Pius IX. erklärte ihn 1851 zum Kirchenlehrer; er ist «der Athanasius des Westens». Benedikt XVI. lobte (2007) sein Suchen nach dem Sinn hinter den Worten der Parteien.`,
		particular: `Er hielt mit den Vätern vor Augustinus die Gotteserscheinungen des Alten Testaments für den Sohn. Er lehrte auch, der Leib Christi habe, so wie er war, den Schmerz nicht empfunden wie der unsere, eine Ansicht, der die Kirche nicht folgte.`,
		feast: '13. Januar',
		titles: 'Kirchenlehrer · Athanasius des Westens'
	},
	tertullian: {
		dates: 'um 155–nach 220 · Karthago',
		life: `In Karthago als Sohn heidnischer Eltern geboren, in Rhetorik und Recht geschult, wurde Tertullian um 195 Christ und schrieb, verheiratet, für die Kirche Afrikas mit der Wucht eines Anwalts. Sein Apologeticum (197) sagte den Statthaltern, «das Blut der Christen ist Same». Um 207 zog ihn der Rigorismus der Montanisten, die «Neue Prophetie» mit ihren Fasten und ihrer Verweigerung einer zweiten Busse, von der katholischen Gemeinde weg; Augustinus sagt, er habe in einer eigenen Sekte geendet. Über seinen Tod ist nichts bekannt.`,
		teaching: `Er schuf das lateinische theologische Vokabular: «trinitas», «eine Substanz, drei Personen», «sacramentum», «Genugtuung». Gegen Praxeas lehrte er die Unterscheidung der Personen; in Über die Einrede gegen die Häretiker argumentierte er, die Schrift gehöre der Kirche, und Häretiker hätten kein Recht, sie zu gebrauchen; Über die Seele hielt die Seele für «von Natur aus christlich». «Was hat Athen mit Jerusalem zu tun?» stammt von ihm, obwohl er Athen trotzdem benutzte.`,
		church: `Tertullian ist kein Heiliger und kein Kirchenlehrer; er wird für seine rechtgläubigen Werke als Vater gelesen. Benedikt XVI. nannte ihn (2007) «einen grossen Vater», dessen Fall «eine Warnung» ist: Der glänzende Geist, der die Geduld der Kirche mit den Schwachen nicht erträgt, endet in der Isolation.`,
		particular: `Er war der erste christliche Autor, der ausführlich lateinisch schrieb, und gab dem Westen seine Begriffe, bevor er seine Konzilien hatte. Seine späten Werke verbieten die Wiederheirat, die Flucht in der Verfolgung und die Vergebung des Ehebruchs. Er ist der einzige Vater, der Häretiker ist und Vater bleibt.`
	},
	cyprian: {
		dates: 'um 200–258 · Karthago',
		life: `Ein wohlhabender Rhetor Karthagos, wurde Cyprian 246 bekehrt, gab seine Gärten den Armen und war binnen drei Jahren Bischof. In der Verfolgung des Decius (250) verbarg er sich, wurde dafür kritisiert und leitete die Kirche aus dem Versteck durch Briefe. Als sie endete, legte er den Weg zurück für die Abgefallenen fest, weder die leichte Verzeihung der Bekenner noch die Verweigerung Novatians, sondern Busse unter dem Bischof. Während der Pest von 252 organisierte er Hilfe für Heiden wie Christen. In der Verfolgung des Valerian wurde er verhört, verbannt, erneut verhört und am 14. September 258 enthauptet, der erste Märtyrerbischof Afrikas.`,
		teaching: `Über die Einheit der katholischen Kirche lehrt, «man kann Gott nicht zum Vater haben, wenn man die Kirche nicht zur Mutter hat», und dass die Einheit auf Petrus gegründet ist; das vierte Kapitel existiert in zwei Fassungen, eine gibt Petrus mehr, beide wohl von ihm. Über die Gefallenen und seine Briefe formten die Bussdisziplin; sein Traktat über das Vaterunser wurde jahrhundertelang gelesen.`,
		church: `Ein Heiliger und Märtyrer, im Römischen Messkanon genannt. Benedikt XVI. nannte ihn (2007) «den ersten Bischof Afrikas, der die Märtyrerkrone erlangte», und den Lehrer der Kirche als Mutter.`,
		particular: `Cyprian hielt mit den Konzilien Afrikas daran fest, dass Konvertiten aus der Häresie neu getauft werden müssten, und Papst Stephan verbot es: «Nichts werde neu eingeführt.» Die Kirche stellte sich später auf Stephans Seite; Augustinus schrieb, Cyprian habe geirrt und die Liebe bewahrt, und sein Martyrium habe den Irrtum abgewaschen. Der Streit ist der klassische Fall eines von Rom korrigierten Heiligen.`,
		feast: '16. September'
	},
	irenaeus: {
		dates: 'um 135–um 202 · Smyrna, Lyon',
		life: `Irenäus hörte als Knabe Polykarp von Smyrna predigen, und Polykarp hatte Johannes gekannt. Als Priester in Lyon brachte er den Brief der Märtyrer von 177 nach Rom und kehrte zurück, um dem gemarterten Bischof Pothinus nachzufolgen. Um 190 bat er Papst Viktor um Frieden mit den Kirchen Asiens über das Osterdatum und wurde seinem Namen, «der Friedliche», gerecht. Eine Überlieferung macht ihn zum Märtyrer unter Septimius Severus.`,
		teaching: `Gegen die Häresien, fünf Bücher gegen die Gnostiker, legte die Glaubensregel dar, die Nachfolge der Bischöfe von den Aposteln als Gewähr der Überlieferung, die vier Evangelien und die Kirche Roms als die Kirche, mit der jede Kirche übereinstimmen muss. Seine Theologie ist die «Rekapitulation»: Christus fasst Adam zusammen und macht seinen Fall rückgängig, Maria löst den Knoten, den Eva geknüpft hat; das Fleisch ist gut und wird auferstehen. «Die Herrlichkeit Gottes ist der lebendige Mensch, das Leben des Menschen aber die Schau Gottes.»`,
		church: `Franziskus erklärte ihn am 21. Januar 2022 zum Kirchenlehrer mit dem Titel «Lehrer der Einheit», der erste im einundzwanzigsten Jahrhundert so benannte Vater. Benedikt XVI. stellte ihn (2007) als den ersten grossen Theologen der Kirche vor.`,
		particular: `Er erwartete ein wörtliches tausendjähriges Reich Christi auf Erden, eine Hoffnung, die die Kirche später beiseitelegte. Seine Darstellung Marias als neuer Eva ist die Wurzel der Marienlehre.`,
		feast: '28. Juni',
		titles: 'Kirchenlehrer · Lehrer der Einheit'
	},
	'clement-alexandria': {
		dates: 'um 150–um 215 · Athen, Alexandrien',
		life: `Wahrscheinlich in Athen als Sohn heidnischer Eltern geboren, reiste Klemens von einem christlichen Lehrer zum andern, bis er Pantainos in Alexandrien fand und ihm um 190 in der Katechetenschule nachfolgte. In der Verfolgung von 202 verliess er die Stadt und starb in Kappadokien. Origenes war sein Schüler.`,
		teaching: `Seine Trilogie führt einen Heiden zum Glauben: der Protreptikos, eine Mahnrede, der Paidagogos, Christus als Lehrer des täglichen Lebens, und die Stromateis, «Teppiche» vermischter Betrachtungen über den «wahren Gnostiker», der durch Glaube und Liebe erkennt. Die Philosophie war ihm ein göttliches Geschenk, das «Alte Testament der Griechen», das sie auf das Evangelium vorbereitete, wie das Gesetz die Juden. In Welcher Reiche wird gerettet? lehrte er, nicht der Reichtum sei der Fehler, sondern das an ihn gehängte Herz.`,
		church: `Klemens' Name stand im Römischen Martyrologium am 4. Dezember, bis Klemens VIII. ihn auf Rat des Baronius wegen Stellen strich, die subordinatianisch klangen oder zu leugnen schienen, dass Christus essen musste; Benedikt XIV. bestätigte die Streichung 1748 und lobte zugleich seine Gelehrsamkeit und sein Leben. Er wird nicht verehrt, doch Benedikt XVI. stellte ihn (2007) ehrenvoll als den ersten Christen vor, der die Philosophie zum Weg zu Christus machte.`,
		particular: `Seine «gnostische» Sprache wurde später gegen ihn gelesen; er meinte den Christen, der versteht, was er glaubt. Er ist der erste Vater, der die heidnischen Dichter so frei zitiert wie die Schrift.`
	},
	'clement-rome': {
		dates: '† um 99 · Rom',
		life: `Klemens war der dritte Nachfolger Petri in Rom, nach Linus und Kletus, und manche Väter setzten ihn mit dem Klemens von Phil 4,3 gleich. Um 96 schrieb er im Namen der römischen Kirche an die Kirche von Korinth, wo die Jungen die Presbyter abgesetzt hatten. Eine spätere Legende lässt ihn auf die Krim verbannt und mit einem Anker ertränkt werden.`,
		teaching: `Der Brief an die Korinther ist die älteste christliche Schrift ausserhalb des Neuen Testaments: Er bittet um Ordnung, Demut und den Frieden der Kirche und gründet das Amt auf eine Nachfolge von den Aposteln, die von Christus gesandt wurden, der von Gott gesandt war. Er wurde in Korinth ein Jahrhundert lang in der Liturgie gelesen und steht in manchen frühen Bibeln.`,
		church: `Ein Heiliger, Apostolischer Vater, im Römischen Kanon genannt. Benedikt XVI. stellte (2007) den Brief als «die erste Ausübung des römischen Primats nach dem Tod Petri» vor. Die Homilie und der Roman unter seinem Namen sind später.`,
		particular: `Rom spricht ungebeten zu Korinth, während der Apostel Johannes noch in Ephesus lebte. Das Gebet des Briefes für die Herrschenden, unter Domitian, ist das Vorbild des kirchlichen Gebets für den Staat.`,
		feast: '23. November'
	},
	ignatius: {
		dates: '† um 107 · Antiochia, Rom',
		life: `Bischof von Antiochia, der zweite oder dritte nach Petrus, wurde Ignatius unter Trajan verurteilt und unter Bewachung nach Rom gebracht, um den Tieren vorgeworfen zu werden. Unterwegs, in Smyrna und Troas, schrieb er sieben Briefe an die Kirchen, die Boten zu seinem Gruss gesandt hatten, und an Polykarp. Er starb im Amphitheater, wahrscheinlich 107.`,
		teaching: `Die Briefe sind der erste Zeuge des dreistufigen Amtes von einem Bischof, Presbytern und Diakonen in jeder Kirche: «Tut nichts ohne den Bischof.» Die Eucharistie ist «das Fleisch unseres Retters Jesus Christus», «die Arznei der Unsterblichkeit»; der Brief nach Smyrna ist der erste Text, der «katholische Kirche» sagt; die Kirche Roms «führt den Vorsitz in der Liebe». Gegen die Doketen besteht er darauf, dass Christus wirklich ass, litt und auferstand. Die Römer bittet er, ihn nicht zu retten: «Ich bin Gottes Weizen, von den Zähnen der Tiere gemahlen.»`,
		church: `Ein Heiliger und Märtyrer, Apostolischer Vater, im Römischen Kanon genannt. Benedikt XVI. nannte ihn (2007) «den Lehrer der Einheit» der frühen Kirche, der Einheit Gottes, Christi und der Kirche.`,
		particular: `Kein Schriftsteller der frühen Kirche spricht so persönlich; seine Briefe waren jahrhundertelang das Muster des Martyriums. Sein Name für sich selbst, «Theophoros», Gottesträger, liess die Legende entstehen, er sei das Kind gewesen, das Jesus in die Mitte der Jünger stellte.`,
		feast: '17. Oktober'
	},
	hippolytus: {
		dates: 'um 170–235 · Rom, Sardinien',
		life: `Ein Priester in Rom, vielleicht Schüler des Irenäus, war Hippolyt der gelehrteste Mann der römischen Kirche und predigte 212 vor dem besuchenden Origenes. Er warf Papst Zephyrinus Modalismus vor und Papst Kallistus Nachsicht gegen Sünder und führte ab 217 eine eigene Partei, der erste Gegenpapst. Kaiser Maximinus verbannte ihn 235 mit Papst Pontianus in die Bergwerke Sardiniens; dort versöhnten sich die beiden und starben. Ihre Leiber wurden am 13. August gemeinsam nach Rom gebracht und beide als Märtyrer geehrt.`,
		teaching: `Er verteidigte die Logostheologie der Apologeten gegen die Modalisten und unterschied Vater und Wort so scharf, dass man ihm zwei Götter vorwarf. Seine Widerlegung aller Häresien führt die Häresien auf die Philosophen zurück; sein Danielkommentar ist der älteste erhaltene christliche Kommentar; sein Traktat über den Antichrist und seine Chronik wurden viel gelesen. Die Apostolische Überlieferung, eine Kirchenordnung mit dem ältesten römischen Hochgebet, läuft seit 1910 unter seinem Namen, doch die Zuschreibung ist heute umstritten; das zweite Hochgebet des Römischen Messbuchs ist daraus geschöpft.`,
		church: `Ein Heiliger und Märtyrer, am 13. August mit Pontianus im Römischen Kalender. Das Schisma wurde in der Versöhnung vergeben; die Verwirrung, die es stiftete, machte ihn in späterer Legende zum Soldatenmärtyrer, von Pferden geschleift. Die sitzende Statue in der Vatikanischen Bibliothek, die seine Werke aufzählt, ist eine restaurierte Figur unsicherer Identität.`,
		particular: `Der einzige Gegenpapst, der als Heiliger verehrt wird. Er hielt die Kirche für eine Gesellschaft der Heiligen und wandte sich gegen die Vergebung schwerer Sünden nach der Taufe, der Rigorismus Tertullians und Novatians.`,
		feast: '13. August'
	},
	justin: {
		dates: 'um 100–165 · Flavia Neapolis, Rom',
		life: `Als Heide in Flavia Neapolis, dem alten Sichem in Samarien, geboren, ging Justin auf der Suche nach Gott von den Stoikern zu den Peripatetikern, den Pythagoreern und den Platonikern, bis ein alter Mann am Meeresufer ihn auf die Propheten und auf Christus wies. Er behielt den Philosophenmantel, lehrte in Rom über einem Badehaus und schrieb zwei Apologien an die Kaiser und den Dialog mit dem Juden Tryphon. Angezeigt, wurde er vor dem Präfekten Junius Rusticus mit sechs Gefährten verhört und um 165 enthauptet; das Protokoll des Prozesses ist erhalten.`,
		teaching: `Das Wort, das Fleisch wurde, ist der «samenhafte Logos», dessen Samen in jedem Menschen sind, so dass «alles, was von irgendjemand gut gesagt wurde, uns Christen gehört» und Sokrates in gewissem Sinn schon vor Christus ein Christ war. Die Erste Apologie enthält die früheste Beschreibung der Sonntagseucharistie: die Lesungen, die Predigt, die Gebete, Brot und Wein, «die wir Eucharistie nennen», über die «der Vorsteher Dank sagt». Im Dialog argumentiert er, die Gotteserscheinungen des Alten Testaments seien das Wort gewesen.`,
		church: `Ein Heiliger und Märtyrer, der erste christliche Philosoph. Benedikt XVI. stellte ihn (2007) als den vor, der das Christentum zur «wahren Philosophie» machte, und das Zweite Vatikanum übernahm seine «Samen des Wortes» für seine Sicht der anderen Religionen.`,
		particular: `Er ist ein Philosoph, der den Namen nie ablegte und als Märtyrer für denselben Glauben starb, den er begründete. Sein Bericht über die Messe, vor 155, war der, den die Ungläubigen lesen sollten.`,
		feast: '1. Juni'
	},
	'leo-great': {
		dates: '† 461 · Rom',
		life: `Ein Tusker, Diakon unter den Päpsten Coelestin und Sixtus III. und schon der fähigste Mann Roms, wurde Leo 440 zum Papst gewählt, während er auf einer Gesandtschaft in Gallien war. 452 traf er Attila am Mincio, und Rom blieb verschont; 455 traf er Geiserich vor den Toren und erhielt das Versprechen, nicht zu brennen und nicht zu morden, obwohl die Vandalen vierzehn Tage plünderten. Er starb am 10. November 461.`,
		teaching: `Sein Tomus an Flavian (449) legte fest, dass in Christus zwei Naturen, jede bewahrend, was ihr eigen ist, in einer Person vereint sind und jede in Gemeinschaft mit der anderen handelt. In Chalkedon 451 verlesen, wurde er mit dem Ruf «Petrus hat durch Leo gesprochen» aufgenommen; den Kanon des Konzils, der Konstantinopel den zweiten Rang gab, wies er zurück. Seine Predigten, sechsundneunzig, machten die Feste zur Lehre: «Christ, erkenne deine Würde.» Er lehrte, Petrus spreche in seinem Nachfolger und die Autorität des Nachfolgers sei die des Petrus.`,
		church: `Benedikt XIV. erklärte ihn 1754 zum Kirchenlehrer, den ersten so benannten Papst. Benedikt XVI. stellte ihn (2008) als den Papst von Chalkedon und der Predigten vor.`,
		particular: `Die Legende von Petrus und Paulus, die über seinem Haupt Attila erscheinen, ist Raffaels; die Quellen sagen nur, der König sei umgekehrt. Er ist der erste Papst, dessen Predigten erhalten sind.`,
		feast: '10. November',
		titles: 'Kirchenlehrer'
	},
	'john-damascene': {
		dates: 'um 675–749 · Damaskus, Mar Saba',
		life: `Johannes wurde in Damaskus unter den Kalifen in eine christliche Familie geboren, die ihnen als Finanzbeamte diente; vielleicht hatte er das Amt seines Vaters inne. Um 725 ging er ins Kloster Mar Saba in der judäischen Wüste, wurde zum Priester geweiht und schrieb dort sicher ausser Reichweite der bilderfeindlichen Kaiser Konstantinopels, die ihn namentlich verfluchten. Er starb um 749.`,
		teaching: `Seine drei Reden gegen die Verleumder der heiligen Bilder (726–730) gaben die Theologie der Ikonen: Die Materie ist nicht böse, da Gott Materie wurde und durch Materie rettete, «ich verehre nicht die Materie, sondern den Schöpfer der Materie, der um meinetwillen Materie wurde»; Verehrung ist nicht Anbetung. Die Quelle der Erkenntnis mit ihrem dritten Teil, der Genauen Darlegung des orthodoxen Glaubens, war die erste Summe der Theologie und speiste in lateinischer Übersetzung Petrus Lombardus und Thomas von Aquin. Seine Homilien zur Entschlafung lehren Marias Aufnahme in den Himmel; seine Kanones werden zum byzantinischen Osterfest gesungen. Den Islam behandelte er als christliche Häresie.`,
		church: `Leo XIII. erklärte ihn 1890 zum Kirchenlehrer. Das Zweite Konzil von Nizäa (787) bestätigte seine Bilderlehre. Benedikt XVI. stellte ihn (2009) als den letzten der griechischen Väter und den Lehrer der Güte der Materie vor.`,
		particular: `Er schrieb im Kalifat, in einer Freiheit, die der byzantinische Kaiser nicht erlaubte; die Bilderlehre der Kirche wurde unter muslimischer Herrschaft ausgearbeitet. Seine Hymnen wie seine Summe waren zum Gebrauch bestimmt, nicht zur Bewunderung.`,
		feast: '4. Dezember',
		titles: 'Kirchenlehrer'
	},
	cassian: {
		dates: 'um 360–435 · Skythien, Ägypten, Marseille',
		life: `Wahrscheinlich in Scythia Minor, der rumänischen Dobrudscha, geboren, trat Cassian um 380 in ein Kloster in Bethlehem ein und verbrachte mit seinem Freund Germanus über ein Jahrzehnt bei den Mönchen Ägyptens. Von Chrysostomus in Konstantinopel zum Diakon geweiht, vertrat er 405 die Sache des verbannten Bischofs in Rom. Um 415 gründete er in Marseille zwei Klöster, für Männer und für Frauen, und schrieb dort für die Mönche Galliens bis zu seinem Tod.`,
		teaching: `Die Institutiones beschreiben das Leben des Zönobiten und die acht Hauptlaster; die Collationes geben die Lehre der Wüstenväter über Gebet, Unterscheidung, Reinheit des Herzens und Schriftlesung wieder. Benedikt schrieb sie zur Lesung nach dem Abendessen vor, und durch ihn prägten sie das westliche Mönchtum. Über die Menschwerdung schrieb er auf Bitten Leos gegen Nestorius.`,
		church: `Ein Heiliger in Marseille und im Osten, mit Fest am 23. Juli im Römischen Martyrologium; nie Kirchenlehrer. Seine dreizehnte Collatio hält daran fest, dass der Anfang des Glaubens vom Menschen ausgehen kann, was Prosper von Aquitanien als pelagianisch angriff, und das Konzil von Orange (529) verurteilte den Semipelagianismus, ohne ihn zu nennen. Die Kirche behielt seine Mönchslehre und korrigierte seine Gnadenlehre.`,
		particular: `Die Kirche ehrt als Heiligen den Mann, an dessen Namen ein Irrtum hängt. Seine «Reinheit des Herzens» als Ziel des Mönchs und seine acht Laster wurden durch Gregor den Grossen zu den sieben Todsünden.`,
		feast: '23. Juli'
	},
	eusebius: {
		dates: 'um 260–339 · Caesarea in Palästina',
		life: `Schüler und Adoptivsohn des Märtyrers Pamphilus, dessen Namen er annahm, wuchs Eusebius in der Bibliothek auf, die Origenes in Caesarea hinterlassen hatte, und wurde um 313 deren Bischof. In Nizäa (325) sass er zur Rechten Konstantins, hielt die Eröffnungsrede und unterschrieb das Bekenntnis mit einem Brief voller Vorbehalte an seine Gemeinde. Vor dem Konzil hatte er Arius verteidigt, danach gegen Athanasius gearbeitet, in Tyrus 335. Er starb um 339.`,
		teaching: `Die Kirchengeschichte in zehn Büchern ist die Aufzeichnung der ersten drei Jahrhunderte und bewahrt sonst verlorene Quellen; die Chronik stellte die Geschichte der Völker in Paralleltafeln; die Vorbereitung und der Erweis des Evangeliums sind die gelehrteste Apologetik der alten Kirche; das Onomastikon verzeichnet die Orte der Bibel, die Kanontafeln die Parallelen der Evangelien. Seine Kommentare zu den Psalmen und Jesaja sind wörtlich in der Art des Origenes.`,
		church: `Eusebius ist kein Heiliger: Seine Sympathie für Arius, sein Feldzug gegen Athanasius und seine Schmeichelei gegenüber Konstantin hielten ihn vom Kalender fern. Benedikt XVI. nannte ihn (2007) dennoch «den ersten Historiker des Christentums» und «den grössten Philologen der alten Kirche» und entnahm ihm die Lesung der Geschichte als Spur der Liebe Gottes.`,
		particular: `Ohne ihn wäre die frühe Kirche fast stumm; mit ihm spricht sie in der Stimme des Kaiserhofs. Sein Leben Konstantins gibt die Vision des Kreuzes vor der Milvischen Brücke wieder, unter dem Eid des Kaisers.`
	},
	chrysologus: {
		dates: 'um 380–450 · Imola, Ravenna',
		life: `In Imola geboren, wurde Petrus um 433 von Papst Sixtus III. gegen den Willen der örtlichen Wähler zum Bischof von Ravenna gemacht, als Ravenna Residenz des weströmischen Hofes war. Er predigte vor der Kaiserin Galla Placidia, die ihm den Namen «Goldwort» gegeben haben soll. Er starb um 450 in Imola.`,
		teaching: `Hundertsechsundsiebzig seiner Predigten sind erhalten, kurz, schlicht und genau, zu den Evangelien des Jahres, dem Glaubensbekenntnis und dem Vaterunser; er drängte zur täglichen Kommunion, lehrte Marias immerwährende Jungfräulichkeit und die Vergebung der Sünden und predigte gegen Arianer und Monophysiten in einer Stadt, in der beide einen Hof hatten.`,
		church: `Benedikt XIII. erklärte ihn 1729 zum Kirchenlehrer. Sein Brief an Eutyches (449), der ihm rät, sich dem Bischof von Rom zu unterwerfen, «weil Petrus in seinem Sitz lebt und den Vorsitz führt», ist ein frühes Zeugnis des Primats.`,
		particular: `Er predigte nie lange, «damit das Volk nicht ermüde», und ist der Lehrer der kurzen Homilie. Die Mosaiken Ravennas, die ihn mit der kaiserlichen Familie zeigen, sind fast zeitgenössisch.`,
		feast: '30. Juli',
		titles: 'Kirchenlehrer'
	},
	theophylact: {
		dates: 'um 1050–nach 1107 · Euböa, Konstantinopel, Ohrid',
		life: `In Chalkis auf Euböa geboren, war Theophylakt Diakon der Hagia Sophia und Erzieher des jungen Prinzen Konstantin Dukas, für den er einen Fürstenspiegel schrieb. Um 1078 wurde er Erzbischof von Ohrid, der bulgarischen Kirche unter byzantinischer Herrschaft, und blieb es für den Rest seines Lebens, in seinen Briefen über die «Barbaren» klagend und die Rechte ihrer Kirche gegen die Steuereintreiber verteidigend.`,
		teaching: `Er schrieb Kommentare zum ganzen Neuen Testament ausser der Offenbarung und zu den kleinen Propheten, nüchtern, klar und brauchbar, in enger Abhängigkeit von Chrysostomus, für Leser, die die Väter selbst nicht bewältigen konnten. Thomas zitiert ihn in der Catena Aurea; Erasmus benutzte ihn unter dem verstümmelten Namen «Vulgarius» für das griechische Neue Testament.`,
		church: `Ein Heiliger der orthodoxen Kirche (31. Dezember), nicht des römischen Kalenders; Katholiken lesen ihn als Zeugen der griechischen Tradition. Zum Filioque schrieb er, der Unterschied zwischen Griechen und Lateinern sei einer der Worte, nicht des Glaubens, eine gemässigte Stimme eine Generation nach dem Schisma von 1054.`,
		particular: `Der letzte der griechischen Kommentatoren im Leser und die Brücke, über die Chrysostomus das lateinische sechzehnte Jahrhundert erreichte.`
	},
	rabanus: {
		dates: 'um 780–856 · Mainz, Fulda, Tours',
		life: `In Mainz geboren und als Kind der Abtei Fulda übergeben, wurde Hrabanus zu Alkuin nach Tours geschickt, der ihn nach Benedikts Schüler Maurus nannte. Er leitete die Schule in Fulda, war von 822 bis 842 Abt und von 847 bis zu seinem Tod am 4. Februar 856 Erzbischof von Mainz. Seine Schüler nannten ihn «Lehrer Deutschlands».`,
		teaching: `Er schrieb Kommentare zum grössten Teil der Bibel, aus den Vätern zusammengestellt für Mönche und Kleriker ohne Bibliotheken; De universo, eine Enzyklopädie der Dinge und ihrer Bedeutungen; ein Handbuch für den Klerus; ein Martyrologium; und Gedichte, darunter die Figurengedichte Zum Lob des heiligen Kreuzes. Der Hymnus Veni Creator Spiritus wird ihm zugeschrieben. Auf der Synode von Mainz 848 verurteilte er die Lehre des Mönchs Gottschalk von der doppelten Prädestination.`,
		church: `«Selig» in den Kalendern von Mainz, Fulda und Limburg (4. Februar), nie förmlich heiliggesprochen. Benedikt XVI. stellte ihn (2009) als den Lehrer vor, für den der Glaube den ganzen Menschen berührt, in Wort, Bild und Gesang, und die Liturgie die Schule der Schönheit ist.`,
		particular: `Hrabanus erhob keinen Anspruch auf Originalität: Er ordnete die Väter, damit die karolingische Kirche sie lesen konnte. Seine Figurengedichte sind Bilder aus Buchstaben, zugleich zu lesen und zu betrachten.`,
		feast: '4. Februar'
	},
	alcuin: {
		dates: 'um 735–804 · York, Aachen, Tours',
		life: `An der Domschule von York erzogen und nach Ælberht ihr Leiter, traf Alkuin Karl den Grossen 781 in Parma und folgte ihm nach Aachen, um die Hofschule zu führen, wo er den König und seine Familie unterrichtete und den Hof zum Zentrum der Gelehrsamkeit des Westens machte. 796 wurde er Abt von Sankt Martin in Tours, wo er Schule und Skriptorium aufbaute, und starb am 19. Mai 804.`,
		teaching: `Seine Lehrbücher zu Grammatik, Rhetorik und Dialektik in Dialogform lehrten die freien Künste über Jahrhunderte; er überarbeitete für den Kaiser den Text der Vulgata, ergänzte das römische Sakramentar um die gallischen Feste und schrieb Kommentare zu Genesis, Psalmen, Hohelied und Johannes. Gegen den Adoptianismus, die spanische Lehre, Christus als Mensch sei Gottes Adoptivsohn, schrieb er sieben Bücher und bewog dessen Urheber Felix 799 in Aachen zum Widerruf.`,
		church: `In manchen Kalendern «selig» genannt (20. Mai), ohne förmlichen Kult in der römischen Kirche. Er ist der Kopf der karolingischen Renaissance, «der Schulmeister seines Zeitalters».`,
		particular: `Er sagte Karl dem Grossen, der Glaube könne den Sachsen nicht aufgezwungen werden und von den Neubekehrten dürfe man keinen Zehnten fordern, eine der wenigen Stimmen gegen die Zwangsbekehrungen. Er unterzeichnete als «Flaccus», nach Horaz.`
	},
	remigius: {
		dates: 'um 841–908 · Auxerre, Reims, Paris',
		life: `Ein Mönch von Saint-Germain in Auxerre, Schüler Heirics und durch ihn Haimos, lehrte Remigius in Auxerre, wurde 893 von Erzbischof Fulko nach Reims berufen, um dessen Schulen wiederherzustellen, und lehrte am Ende seines Lebens in Paris. Er starb 908.`,
		teaching: `Er kommentierte Genesis, Psalmen, kleine Propheten und Matthäus und glossierte die Schulautoren Donatus, Boethius, Martianus Capella, aus Eriugena und der karolingischen Tradition schöpfend. Grammatik und freie Künste waren ihm der Weg in die Schrift. Die Catena Aurea zitiert ihn zu Matthäus.`,
		church: `Kein Kult. Er ist der letzte Lehrer der karolingischen Schulen, dessen Glossen das zwölfte Jahrhundert speisten.`,
		particular: `Nicht zu verwechseln mit Remigius von Reims, dem Bischof, der Chlodwig taufte, unter dessen Namen ihn manche Quellen führen.`
	},
	haimo: {
		dates: '† um 865 · Auxerre',
		life: `Ein Mönch von Saint-Germain in Auxerre, Lehrer Heirics, ist Haimo nur aus seinen Werken bekannt; die karolingische Schule von Auxerre, Haimo, Heiric, Remigius, ist ihre Folge von Meistern.`,
		teaching: `Er schrieb Kommentare zu Paulus, zur Offenbarung, zu Jesaja, den kleinen Propheten und dem Hohelied, aus den Vätern zusammengestellt und zu einer eigenen Lehre über die Realpräsenz in der Eucharistie und über die Kirche geschärft. Sein Offenbarungskommentar speiste Adsos Brief über den Antichrist.`,
		church: `Kein Kult. Acht Jahrhunderte lang wurden seine Werke unter dem Namen Haymos von Halberstadt gedruckt, eines Bischofs desselben Jahrhunderts, und stehen so in Mignes Patrologie; die Catena Bible führt ihn als «Haymo».`,
		particular: `Der erste mittelalterliche Kommentator, der Paulus ausführlich durch Augustins Gnadenlehre las, und ein früher Zeuge des eucharistischen Realismus, den der Streit um Berengar später zum Dogma machte.`
	},
	lactantius: {
		dates: 'um 250–325 · Afrika, Nikomedien, Trier',
		life: `Ein afrikanischer Schüler des Arnobius, wurde Laktanz von Diokletian nach Nikomedien berufen, um lateinische Rhetorik zu lehren, und verlor seinen Lehrstuhl, als 303 die Verfolgung begann. Er schrieb in Armut, und um 317 machte ihn Konstantin in Trier zum Lehrer seines Sohnes Crispus.`,
		teaching: `Die Divinae institutiones in sieben Büchern sind der erste Versuch einer vollständigen Darstellung der christlichen Lehre auf Lateinisch, an den gebildeten Heiden nach Ciceros Art gerichtet; die Humanisten nannten ihn «den christlichen Cicero». Über die Todesarten der Verfolger erzählt, wie jeder Verfolger ein schlimmes Ende nahm, und bewahrt die Geschichte von Konstantins Vision. Über das Schöpfungswerk Gottes und Über den Zorn Gottes sind apologetisch.`,
		church: `Kein Heiliger. Hieronymus wünschte, «er hätte das Unsere so gut gelehrt, wie er das Fremde zerstörte»: Seine Theologie ist dünn, er hielt ein wörtliches Tausendjähriges Reich, behandelte den Teufel fast als zweites Prinzip und sagte wenig vom Heiligen Geist. Das Decretum Gelasianum des sechsten Jahrhunderts zählte seine Werke zu den Apokryphen.`,
		particular: `Man liest ihn für sein Latein und seine Geschichte, nicht für seine Lehre; der Leser hat ihn als Zeugen des konstantinischen Zeitalters.`
	},
	anselm: {
		dates: '1033–1109 · Aosta, Bec, Canterbury',
		life: `In Aosta geboren, verliess Anselm nach einem Streit mit seinem Vater das Haus, wanderte durch Burgund und die Normandie und trat 1060 unter Lanfranc in die Abtei Bec ein. Mit dreissig war er Prior, 1078 Abt und 1093 Erzbischof von Canterbury, ein Amt, das Wilhelm Rufus ihm aufzwang und dann mit ihm bekämpfte. Zweimal wegen des königlichen Anspruchs, Bischöfe einzusetzen, verbannt, unter Wilhelm und Heinrich I., setzte er sich 1107 durch und starb am 21. April 1109 in Canterbury.`,
		teaching: `Das Monologion schliesst aus den guten Dingen, die wir kennen, auf Gott; das Proslogion findet in der Bestimmung «das, worüber hinaus nichts Grösseres gedacht werden kann» einen Beweis, dass Gott existiert, das «ontologische Argument», das Thomas verwarf und Bonaventura, Descartes und Hegel behielten. Cur Deus homo erklärt die Menschwerdung durch die Genugtuung: Die Sünde schuldet Gott eine Ehre, die nur Gott zahlen kann und nur der Mensch zahlen soll, also zahlt sie der Gottmensch. Seine Gebete und Betrachtungen begannen die affektive Frömmigkeit des Mittelalters. «Der Glaube, der nach Einsicht sucht», «ich glaube, um zu verstehen», sind seine Regel.`,
		church: `Klemens XI. erklärte ihn 1720 zum Kirchenlehrer, «der herrliche Lehrer», der Vater der scholastischen Theologie. Benedikt XVI. stellte (2009) seine drei Stufen Glaube, Erfahrung und Betrachtung und seinen Mut vor den Königen vor.`,
		particular: `Sein Schüler Eadmer führte seine Lehre von der Erbsünde weiter, als er selbst es tat, um Marias Unbefleckte Empfängnis zu begründen, die Anselm nicht vertrat. Er weigerte sich, Erzbischof zu werden, bis die Bischöfe ihm den Stab in die Hand zwangen.`,
		feast: '21. April',
		titles: 'Kirchenlehrer · der herrliche Lehrer'
	},
	bernard: {
		dates: '1090–1153 · Fontaines, Cîteaux, Clairvaux',
		life: `In Fontaines bei Dijon in den niederen Adel geboren, trat Bernhard 1112 mit dreissig Verwandten und Freunden, die er überredet hatte, in das neue Kloster Cîteaux ein. 1115 wurde er zur Gründung von Clairvaux ausgesandt und lenkte von jenem Tal aus das Wachstum der Zisterzienser auf achtundsechzig Tochterklöster zu seinen Lebzeiten. Er entschied das Papstschisma von 1130 für Innozenz II., liess Abaelard 1140 in Sens verurteilen, predigte 1146 in Vézelay den Zweiten Kreuzzug und trug die Schuld an dessen Scheitern. Er starb am 20. August 1153.`,
		teaching: `Die sechsundachtzig Predigten zum Hohelied, die nur bis zum dritten Kapitel gelangen, sind der Klassiker der westlichen mystischen Theologie, die Seele als Braut des Wortes. Über die Gottesliebe setzt vier Grade der Liebe; Über Gnade und freie Entscheidung versöhnt Augustinus mit der Freiheit; das Buch der Betrachtung sagte seinem einstigen Mönch, Papst Eugen III., wozu ein Papst da ist. Seine Marienpredigten, «schau auf den Stern, rufe Maria an», machten ihn zum Lehrer der Marienverehrung.`,
		church: `1174 heiliggesprochen, 1830 von Pius VIII. zum Kirchenlehrer erklärt, «der honigfliessende Lehrer». Benedikt XVI. stellte ihn (2009) neben Abaelard als den Theologen des Herzens: «Gott wird besser im Gebet gesucht als in der Disputation.»`,
		particular: `Bernhard wandte sich in einem Brief an die Kanoniker von Lyon (1140) gegen das neue Fest der Empfängnis Marias, weil er sie nach der Empfängnis im Mutterleib geheiligt sah, die Ansicht, die Thomas teilen sollte; das Dogma von 1854 entschied anders. Seine Polemik gegen die Kirchen von Cluny, ihre Grösse und ihre Skulpturen, ist die zisterziensische Ästhetik in einem Absatz.`,
		feast: '20. August',
		titles: 'Kirchenlehrer · der honigfliessende Lehrer'
	},
	aquinas: {
		dates: '1224/5–1274 · Roccasecca, Paris, Neapel, Fossanova',
		life: `In Roccasecca, der Burg der Grafen von Aquino, geboren, wurde Thomas mit fünf nach Monte Cassino gegeben und mit vierzehn an die Universität Neapel geschickt, wo er die Dominikaner kennenlernte und 1244 zu ihnen ging. Seine Brüder ergriffen ihn und hielten ihn ein Jahr in der Familienburg fest; er änderte seine Meinung nicht. Unter Albert dem Grossen in Paris und Köln war er «der stumme Ochse»; in Paris wurde er 1256 Magister der Theologie und lehrte dann in Orvieto, Rom, wieder Paris und Neapel.

Am 6. Dezember 1273 hörte er nach der Messe auf zu schreiben: «Alles, was ich geschrieben habe, scheint mir Stroh gegenüber dem, was ich gesehen habe.» Er starb am 7. März 1274 in der Zisterzienserabtei Fossanova auf dem Weg zum Konzil von Lyon.`,
		teaching: `Die Summa theologiae, fünfhundertzwölf Quaestionen, unvollendet, ordnet die ganze Theologie von Gott über die Schöpfung zur Rückkehr des Menschen zu Gott in Christus und den Sakramenten; die Summa contra gentiles argumentiert mit denen, die keine Schrift teilen. Er kommentierte Aristoteles und Ijob, Psalmen, Jesaja, Jeremia, Matthäus, Johannes und Paulus. Die Catena Aurea, für Urban IV. verfasst (1263–1268), reiht die Väter, griechische und lateinische, zu einer fortlaufenden Glosse zu den vier Evangelien; die Kette im Leser ist die seine.

Die Gnade vollendet die Natur und zerstört sie nicht; Glaube und Vernunft sind zwei Wege zu einer Wahrheit; die fünf Wege führen von der Welt zu Gott; die Eucharistie ist Wesensverwandlung. Er schrieb das Offizium von Fronleichnam, «Pange lingua», «Adoro te».`,
		church: `1323 heiliggesprochen, 1567 von Pius V. zum Kirchenlehrer erklärt und «der allgemeine Lehrer» und «der engelgleiche Lehrer» genannt. Leos XIII. Aeterni Patris (1879) machte ihn zur Norm der katholischen Philosophie; das Zweite Vatikanum und das Kirchenrecht nennen ihn noch als Lehrer der Seminaristen. Benedikt XVI. widmete ihm drei Katechesen (2010).`,
		particular: `Vor dem Kreuz in Neapel hörte man ihm sagen: «Du hast gut über mich geschrieben, Thomas; welchen Lohn willst du?», und ihn antworten: «Nichts als dich selbst, Herr.» Die Unbefleckte Empfängnis in der damals vorgeschlagenen Form lehnte er ab und hielt Maria für nach der Beseelung geheiligt; das Dogma von 1854 folgte Scotus. Er ist ein Mittelalterlicher, kein Vater, und erscheint im Leser als der Sammler der Väter.`,
		feast: '28. Januar',
		titles: 'Kirchenlehrer · der engelgleiche Lehrer · der allgemeine Lehrer'
	},
	glossa: {
		dates: '12. Jahrhundert · Laon, Paris',
		life: `Die Glossa Ordinaria ist keine Person, sondern der Standardkommentar der mittelalterlichen Schulen: kurze Auszüge aus den Vätern, an den Rand der lateinischen Bibel und zwischen ihre Zeilen geschrieben. Begonnen in Laon von Anselm von Laon († 1117) und seinem Bruder Radulf, fortgeführt von Gilbert dem Universalen zum Alten Testament und in der zweiten Hälfte des zwölften Jahrhunderts in Paris vollendet, wo Petrus Lombardus' Glossen zu den Psalmen und Paulus die älteren ersetzten.`,
		teaching: `Die Quellen sind Augustinus, Hieronymus, Gregor, Beda, Isidor, Hrabanus, Haimo und Origenes auf Lateinisch. Jeder Theologiestudent las die Bibel mit der Glosse darum herum; Thomas zitiert «die Glosse» als Autorität für sich, und in der Catena Aurea ist die «Interlinearglosse» eine Stimme unter den Vätern.`,
		church: `Sie wurde Walahfrid Strabo zugeschrieben, bis Beryl Smalley im zwanzigsten Jahrhundert den Ursprung in Laon nachwies. Zuerst 1480/81 in Strassburg von Adolph Rusch gedruckt, blieb sie bis in die frühe Neuzeit der Referenzkommentar, bis die Postillen Hugos von Saint-Cher und Nikolaus' von Lyra ihre Stelle einnahmen.`,
		particular: `Der Leser zeigt sie mit Initialen, da es kein Gesicht zu zeigen gibt. Ihre Einträge in der Kette sind die anonyme Stimme der mittelalterlichen Schule.`
	},
	lapide: {
		dates: '1567–1637 · Bocholt, Löwen, Rom',
		life: `In Bocholt im flämischen Kempenland geboren, studierte Cornelis van den Steen, lateinisch «a Lapide», in Maastricht, Köln, Douai und Löwen und trat 1592 in den Jesuitenorden ein. Er lehrte Schrift und Hebräisch in Löwen ab 1596 und am Römischen Kolleg ab 1616 bis zu seinem Tod am 12. März 1637.`,
		teaching: `Er kommentierte jedes Buch der Bibel ausser Ijob und den Psalmen, in Foliobänden von 1614 bis 1645, die zu jedem Vers die Väter, die Rabbinen und die Scholastiker sammeln und den wörtlichen, allegorischen, moralischen und anagogischen Sinn nebeneinander geben, mit dem Prediger im Blick. Die Kommentare wurden zwei Jahrhunderte lang in ganz Europa nachgedruckt; die englische Übersetzung der Evangelien (1876–1908) ist die Quelle der Auszüge im Leser.`,
		church: `Kein Verfahren wurde eröffnet; er wird als der grosse katholische Kommentator der Gegenreformation geehrt, «der bedeutendste der katholischen Schriftkommentatoren» nach dem Urteil seiner Zeit, und Haydock schöpfte durchgehend aus ihm.`,
		particular: `Lapide ist eine Bibliothek zu jedem Vers, die mehr sammelt, als sie urteilt. Er ist der letzte der Kommentatoren, der die vier Schriftsinne mit gleichem Gewicht gibt.`
	},
	haydock: {
		dates: '1774–1849 · Cottam, Douai, Penrith',
		life: `In Cottam in Lancashire in eine alte rekusantische Familie geboren, studierte George Leo Haydock in Douai und floh 1793 vor der Französischen Revolution, um in Crook Hall abzuschliessen. 1798 geweiht, betreute er die Missionen von Ugthorpe in den Mooren Yorkshires, Whitby, Westby und Penrith, wurde 1831 bis 1839 in einem Streit mit seinem Bischof suspendiert und wieder eingesetzt und starb am 29. November 1849 in Penrith.`,
		teaching: `Die Haydock-Bibel (Manchester 1811–1814, gedruckt von seinem Bruder Thomas) setzte den Text der Douay-Rheims in einen Kommentar, der aus den Vätern und aus Calmet, Estius, Menochius, Tirinus und Witham zusammengestellt war, mit eigenen Anmerkungen gegen protestantische und deistische Einwände. Sie war die beliebteste englische katholische Bibel des neunzehnten Jahrhunderts, hundert Jahre lang in Amerika und Irland nachgedruckt.`,
		church: `Ein Pfarrer und Kompilator, ohne Verfahren oder Titel. Seine Anmerkungen sind vorkritisch und oft polemisch und werden heute als Zeugnis der katholischen Apologetik vor der Bibelbewegung gelesen.`,
		particular: `Haydock ist die «neuere» Stimme im Leser, standardmässig aus: kurz, kämpferisch und praktisch, die Anmerkung, die ein Priester von der Kanzel lesen konnte.`
	},
	challoner: {
		dates: '1691–1781 · Lewes, Douai, London',
		life: `In Lewes in Sussex als Sohn eines presbyterianischen Küfers und einer Mutter, die im Dienst katholisch wurde, geboren, wurde Challoner 1705 nach Douai geschickt und verbrachte dort fünfundzwanzig Jahre als Student, Professor und Vizepräsident. Ab 1730 wirkte er in London verkleidet unter den katholischen Armen, wurde 1741 Koadjutor und 1758 Apostolischer Vikar des Londoner Distrikts. Während der Gordon-Unruhen von 1780 versteckten Freunde den neunundachtzigjährigen Bischof; er starb am 12. Januar 1781 und wurde 1946 in der Westminster Cathedral neu bestattet.`,
		teaching: `Er überarbeitete die Douay-Rheims-Bibel (1749–1752), ersetzte ihr latinisiertes Englisch durch schlichtere Wörter und fügte kurze Anmerkungen hinzu; die «Douay»-Bibel, die englischsprachige Katholiken bis ins zwanzigste Jahrhundert lasen, und der englische Text in diesem Leser sind die seinen. Der Garten der Seele (1740) war zwei Jahrhunderte lang das englische katholische Gebetbuch; die Memoiren der Missionspriester (1741) hielten die Märtyrer der Reformation fest und bereiteten ihre Heiligsprechung vor.`,
		church: `Nicht seliggesprochen; geehrt als der Bischof, der den Glauben in England in seinen dunkelsten Jahren am Leben hielt. Kardinal Newman nannte die Katholiken seiner Zeit «die Kirche Challoners».`,
		particular: `Seine Anmerkungen im Leser sind die Randnotizen eines Bischofs für Menschen, die kein anderes Buch hatten: kurz, lehrhaft und darauf bedacht, die Lesart der Kirche zu verteidigen.`
	},
	erasmus: {
		dates: '1466/9–1536 · Rotterdam, Löwen, Basel',
		life: `Der uneheliche Sohn eines Priesters, wurde Erasmus zu den Augustinerchorherren in Steyn gegeben, 1492 geweiht und durch päpstlichen Dispens vom Kloster befreit. Er studierte in Paris, fand in England Freunde in More und Colet und lebte von seiner Feder in Löwen, Basel und Freiburg als der berühmteste Gelehrte Europas. Er starb am 12. Juli 1536 in Basel.`,
		teaching: `Sein Novum Instrumentum (1516) war das erste gedruckte griechische Neue Testament, mit neuer lateinischer Übersetzung und Annotationen, die die moderne Textforschung begründeten; seine Paraphrasen zum Neuen Testament wurden unter Eduard VI. von jeder englischen Kanzel gelesen. Das Enchiridion lehrte eine innerliche Frömmigkeit, das Lob der Torheit verspottete die Missbräuche der Kirche; seine Ausgaben von Hieronymus, Cyprian, Ambrosius und Augustinus gaben dem sechzehnten Jahrhundert die Väter.`,
		church: `Er weigerte sich, Luther zu folgen, antwortete ihm über den freien Willen (1524) und erhielt Vom unfreien Willen zur Antwort. Der Index Pauls IV. von 1559 verbot alle seine Werke, der Index von Trient (1564) nur einige; die Sorbonne hatte 1527 zweiunddreissig Sätze zensuriert. Heute liest man ihn als den katholischen Reformer, der in der Kirche blieb, und seine Annotationen sind der «Erasmus» im Leser.`,
		particular: `Erasmus zweifelte am Comma Johanneum und an der Verfasserschaft des Hebräerbriefs, stellte Reliquien und Wallfahrten in Frage und sagte, «die Summe unserer Religion ist Friede». Er ist der Humanist unter den Kommentatoren und der einzige, der nie von Beruf Theologe war.`
	},
	ambrosiaster: {
		dates: 'wirkte 366–384 · Rom',
		life: `«Ambrosiaster» ist der Name, den Erasmus 1527 dem unbekannten Verfasser eines Kommentars zu den dreizehn Paulusbriefen gab, geschrieben in Rom unter Papst Damasus, der jahrhundertelang als Werk des Ambrosius galt. Wer er war, ist noch umstritten: ein römischer Priester, vielleicht der Diakon Hilarius, vielleicht der bekehrte Jude Isaak.`,
		teaching: `Sein Kommentar ist wörtlich, historisch und nüchtern, die beste lateinische Paulusexegese vor Pelagius, und die Fragen zum Alten und Neuen Testament unter Augustins Namen sind ebenfalls die seinen. Zu Röm 5,12 las er «in dem alle gesündigt haben» von Adam, und Augustinus nahm die Lesart in seine Erbsündenlehre auf; auch Pelagius benutzte ihn.`,
		church: `Ein Name für einen Text, ohne Kult oder Titel. Man liest ihn als die Stimme der römischen Kirche des vierten Jahrhunderts.`,
		particular: `Der eine Kommentator im Leser ohne Gesicht und ohne Namen, der «Möchtegern-Ambrosius».`
	},
	'pseudo-chrysostom': {
		dates: '5. Jahrhundert',
		life: `Die Catena Aurea zitiert unter dem Namen des Chrysostomus das Opus imperfectum in Matthaeum, einen unvollendeten lateinischen Matthäuskommentar, um 400–450 von einem arianischen Verfasser wohl in den Donauprovinzen geschrieben, den das Mittelalter für eine Übersetzung des Goldmunds hielt. Thomas wusste, dass er verdächtig war, und kennzeichnete ihn; der Leser behält die Bezeichnung, damit die Kette so zu lesen ist, wie er sie schrieb.`
	},
	'pseudo-augustine': {
		dates: '5.–8. Jahrhundert',
		life: `Predigten und Traktate, die unter Augustins Namen umliefen und sich später als Werke anderer erwiesen: Caesarius von Arles, Quodvultdeus, Fulgentius und unbekannte Prediger. Wo die Catena Aurea einen zitiert, bezeichnet ihn der Leser als «Pseudo-Augustinus».`
	},
	'pseudo-jerome': {
		dates: '5.–7. Jahrhundert',
		life: `Texte, die einst unter den Werken des Hieronymus gedruckt wurden und heute als nicht von ihm gelten, vor allem das Breviarium in Psalmos und der Markuskommentar, den die Catena Aurea zitiert. Der Leser behält die Bezeichnung, die Thomas' Quellen geben.`
	},
	'greek-expositor': {
		dates: 'verschieden',
		life: `Die Catena Aurea zitiert bisweilen ein griechisches Scholion, dessen Verfasser ihre Quelle nicht nannte oder mit einem Namen versah, den Thomas nicht prüfen konnte: Der Leser führt sie als «ein griechischer Ausleger», wie er es tat.`
	},
	'douay-1609': {
		dates: '1582–1610 · Reims, Douai',
		life: `Die Annotatoren der ursprünglichen Douay-Rheims-Bibel, des Neuen Testaments des Englischen Kollegs von 1582 und des Alten Testaments von 1609–1610: Gregory Martin, William Allen, Richard Bristow und Thomas Worthington. Ihre Anmerkungen sind lang, gelehrt und polemisch, gegen die protestantischen Übersetzungen geschrieben; Challoner kürzte sie 1750, und die wenigen, die den Leser erreichen, kommen über die Catena Bible.`
	},
	'aquinas-study-bible': {
		dates: '21. Jahrhundert',
		life: `Redaktionelle Anmerkungen einer modernen Sammlung, die zu jedem Vers die Väter und Thomas zusammenträgt; der Leser führt sie als eine der neueren Quellen, standardmässig aus.`
	}
};
